+    expect(dispatch(session, { type: "styleChanged", style: "koto" }, ctx("s1", 5))).toBe(session);
+  });
+});
+
+describe("playlist mode", () => {
+  it("toggles to the first Chopin track, advances, wraps, and exits", () => {
+    let session = entered("s1", 0);
